import json

from settings import load_settings


def test_merges_over_defaults(tmp_path):
    p = tmp_path / "s.json"
    p.write_text(json.dumps({"theme": "dark"}))
    assert load_settings(str(p)) == {"theme": "dark", "lang": "en"}

