import json

DEFAULTS = {"theme": "light", "lang": "en"}


def load_settings(path):
    try:
        with open(path) as f:
            data = json.load(f)
    except FileNotFoundError:
        return dict(DEFAULTS)
    merged = dict(DEFAULTS)
    merged.update(data)
    return merged
